    const A = RV.aedit || u.acc, F = (l, k, o = {}) => `<div class="bm-fld ${o.span ? 'span' : ''}">${App.field(l, `<input type="${o.type || 'text'}" data-in="vr-a" data-k="${k}" value="${esc(k.split('.').reduce((a, p) => a[p], A))}">`, { req: o.req })}${o.help ? `<p class="helper">${o.help}</p>` : ''}</div>`;
